package main

import "fmt"

func main() {
	var a, b, c, d int
	fmt.Scan(&a, &b, &c, &d)

	max := a
	if c < max {
		max = c
	}
	if d < max {
		max = d
	}

	x := 256 * max

	a -= max
	c -= max
	d -= max

	max = a
	if b < max {
		max = b
	}

	x += 32 * max

	fmt.Println(x)
}

